insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-013','json-schema','tool-design','좁은 JSON Schema','입력 범위를 작게 정의해 잘못된 인자를 줄임','구조화된 tool argument가 중요할 때','free-form 텍스트가 핵심 입력일 때','required fields + enums + bounds','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-014','mcp-014','tool-design','도구 이름 설계','행동과 대상을 이름에서 바로 알 수 있게 함','도구 수가 많아 routing이 어려울 때','모든 도구를 vague 이름으로 둘 때','verb_noun, e.g. issue_get / issue_update','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-015','description','tool-design','Description 설계','언제 호출하고 언제 호출하지 말지 설명','비슷한 도구가 여러 개일 때','설명에 마케팅 문구만 넣을 때','purpose + use_when + avoid_when + side_effect','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-016','mcp-016','tool-design','읽기/쓰기 분리','조회와 변경 도구를 별도화','사고로 인한 변경을 줄이고 싶을 때','get_or_update처럼 한 도구에 혼합','read_* vs write_*','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-017','idempotency','tool-design','Idempotency','재시도해도 중복 부작용이 없게 설계','결제·등록·배포 등 쓰기 작업','중복 실행이 치명적인데 key가 없을 때','idempotency_key + operation status','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-018','pagination','tool-design','Pagination','대량 결과를 페이지 단위로 반환','이슈·메일·DB row가 많은 경우','수천 건을 한 번에 LLM에 넣을 때','cursor + limit + next_cursor','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-019','result-compression','tool-design','Result Compression','도구 결과를 필요한 필드만 반환','토큰·지연을 줄여야 할 때','raw API 응답을 그대로 모델에 줄 때','summary + ids + critical fields','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-020','error-taxonomy','tool-design','Error Taxonomy','재시도 가능/불가 오류를 구분','자동 복구 로직이 필요한 경우','모든 오류를 문자열 하나로 반환','code + retryable + user_action','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
insert into public.mcp_patterns(id,slug,category,title,summary,when_to_use,avoid_when,starter_template,checklist,evidence_level,source_refs,last_verified,metadata) values ('mcp-021','retry-budget','tool-design','Retry Budget','무한 tool loop를 막는 제한','외부 API가 불안정할 때','같은 실패를 계속 반복할 때','max_attempts + backoff + fallback','["도구/리소스가 정말 필요한지 먼저 확인","읽기와 쓰기 권한을 분리","입력 스키마와 실패 조건을 명확히 정의","위험한 행동은 사용자 확인 후 실행","로그·재시도·비용 상한을 운영 지표로 남기기"]'::jsonb,'Official concept + production starter',array['mcp-spec','openai-function']::text[],'2026-09-21'::date,'{"status":"starter"}'::jsonb) on conflict(id) do update set slug=excluded.slug,category=excluded.category,title=excluded.title,summary=excluded.summary,when_to_use=excluded.when_to_use,avoid_when=excluded.avoid_when,starter_template=excluded.starter_template,checklist=excluded.checklist,evidence_level=excluded.evidence_level,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
